        return -1 if v < -0.5 else (1 if v > 0.5 else 0)

    def pair(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            a, b = v[0], v[1]
            if isinstance(a, (int, float)) and isinstance(b, (int, float)):
                return a, b
        return default

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(src, dst):
        sx, sy = src
        tx, ty = dst
        return [clamp_step(tx - sx), clamp_step(ty - sy)]

    def step_away(src, dst):
        sx, sy = src
        tx, ty = dst
        return [clamp_step(sx - tx), clamp_step(sy - ty)]

    def in_bounds(p):
        x, y = p
        return 0 <= x < gw and 0 <= y < gh

    def iter_points(items):
        if isinstance(items, dict):
            items = items.values()
        if not isinstance(items, (list, tuple)):
            return
        for it in items:
            if isinstance(it, dict):
                if "position" in it:
                    p = pair(it.get("position"))
                    yield p
                elif "x" in it and "y" in it:
                    yield (it.get("x"), it.get("y"))
            elif isinstance(it, (list, tuple)) and len(it) >= 2:
                yield (it[0], it[1])

    def best_point(src, items, mode="nearest"):
        best = None
        best_score = None
