            score = manhattan(src, p)
            if best is None or (mode == "nearest" and score < best_score) or (mode == "farthest" and score > best_score):
                best = p
                best_score = score
        return best

    def center_point():
        return (gw // 2, gh // 2)

    env = observation.get("environment_name", "") or ""
    sx, sy = pair(observation.get("self_position"))
    ox, oy = pair(observation.get("opponent_position"), (sx, sy))
